import { featureFlags } from "@/config/feature-flags";
import { requirePermission } from "@/server/auth/permissions";
import { getDemoSession } from "@/server/auth/session";
import {
  findComplianceItemsForOrganization,
  findDocumentsForOrganization,
} from "@/server/repositories/compliance-repository";

export type ComplianceRow = {
  id: string;
  title: string;
  status: "Följs" | "Varning" | "Blockerad";
  detail: string;
  propertyName: string;
};

export type DocumentRow = {
  id: string;
  title: string;
  category: string;
  status: "Utkast" | "Aktiv" | "Arkiverad";
  propertyName: string;
};

const fallbackCompliance: ComplianceRow[] = [
  {
    id: "compliance-night-cap",
    title: "Nattantal inom tak",
    status: "Följs",
    detail: "Alla vistelser följer fastigheternas policy.",
    propertyName: "Alla fastigheter",
  },
  {
    id: "compliance-bankid",
    title: "BankID och avtal",
    status: "Följs",
    detail: "Signerade avtal krävs innan incheckning.",
    propertyName: "Alla fastigheter",
  },
  {
    id: "compliance-dac7",
    title: "DAC7-rapportering",
    status: "Följs",
    detail: "Underlag är klart för januari 2027.",
    propertyName: "Alla fastigheter",
  },
];

const fallbackDocuments: DocumentRow[] = [
  {
    id: "doc-standard-host-avtal",
    title: "Standardavtal för boendeuthyrning",
    category: "Avtal",
    status: "Aktiv",
    propertyName: "Alla fastigheter",
  },
  {
    id: "doc-dac7-2026",
    title: "DAC7-underlag 2026",
    category: "Skatt",
    status: "Utkast",
    propertyName: "Alla fastigheter",
  },
];

function complianceStatusLabel(status: "PASSING" | "WARNING" | "BLOCKED") {
  if (status === "PASSING") return "Följs";
  if (status === "WARNING") return "Varning";
  return "Blockerad";
}

function documentStatusLabel(status: "DRAFT" | "ACTIVE" | "ARCHIVED") {
  if (status === "ACTIVE") return "Aktiv";
  if (status === "ARCHIVED") return "Arkiverad";
  return "Utkast";
}

function fallbackOnDatabaseError<T>(promise: Promise<T>, fallback: T): Promise<T> {
  if (!featureFlags.useDatabaseReads) {
    return Promise.resolve(fallback);
  }

  return promise.catch((error) => {
    if (process.env.NODE_ENV === "development") {
      console.warn("Falling back to mock compliance data because Prisma is unavailable.", error);
    }

    return fallback;
  });
}

export async function getOwnerComplianceCenter() {
  const session = await getDemoSession();
  requirePermission(session, "read:organization");

  const [compliance, documents] = await Promise.all([
    fallbackOnDatabaseError(
      findComplianceItemsForOrganization(session.organizationId).then((items) =>
        items.map((item) => ({
          id: item.id,
          title: item.title,
          status: complianceStatusLabel(item.status),
          detail: item.detail ?? "Ingen detalj angiven.",
          propertyName: item.property?.name ?? "Alla fastigheter",
        })),
      ),
      fallbackCompliance,
    ),
    fallbackOnDatabaseError(
      findDocumentsForOrganization(session.organizationId).then((items) =>
        items.map((item) => ({
          id: item.id,
          title: item.title,
          category: item.category,
          status: documentStatusLabel(item.status),
          propertyName: item.property?.name ?? "Alla fastigheter",
        })),
      ),
      fallbackDocuments,
    ),
  ]);

  return { compliance, documents };
}

import { prisma } from "@/server/db/prisma";

export function findComplianceItemsForOrganization(organizationId: string) {
  return prisma.complianceItem.findMany({
    where: { organizationId },
    include: { property: true },
    orderBy: [{ status: "asc" }, { title: "asc" }],
  });
}

export function findDocumentsForOrganization(organizationId: string) {
  return prisma.document.findMany({
    where: { organizationId },
    include: { property: true },
    orderBy: [{ status: "asc" }, { title: "asc" }],
  });
}

